from playwright.sync_api import sync_playwright
import os,json,hashlib
source=(ROOT/'assets/game.js').read_text();probe=r'''
window.__protectedLimit=()=>{__townTest.reset('settlement',42);G.loans=Array.from({length:10000},(_,i)=>({id:i+1,bankId:0,ownerType:'household',ownerId:0,original:100,balance:17,rate:.05,status:'default',term:360,created:1,paid:0,arrears:95,defaultedDay:G.day}));G.nextLoanId=10000;if(!hydrateSave(archivePayload()))throw Error('Protected boundary rejected');const claims=JSON.stringify(G.loans),cash=totalMoney(),loan=bankLoan('household',0,100,360);if(loan||JSON.stringify(G.loans)!==claims||totalMoney()!==cash||!G.households[0].creditDecision.reason.includes('ledger'))throw Error('Protected capacity erased claims');if(!hydrateSave(archivePayload()))throw Error('Protected refusal unimportable');return {protectedDefaults:10000,claimsPreserved:true,explicitRefusal:true};};
window.__loanLimit=()=>{__townTest.reset('settlement',42);__townTest.step(30);const h=G.households.find(h=>h.people.length&&h.cash>1000&&!G.loans.some(l=>l.ownerType==='household'&&l.ownerId===h.id&&l.status==='active'));let loan=bankLoan('household',h.id,100,30);if(!loan)throw Error('Initial real loan refused');for(let i=0;i<31&&loan.status==='active';i++){G.day++;loanPayments([loan]);}if(loan.status!=='repaid'||loan.balance!==0)throw Error('Real repayment failed');const receipt=JSON.parse(JSON.stringify(loan));while(G.loans.length<9997){const l={...receipt,id:++G.nextLoanId};G.loans.push(l);}const protectedRows=[{...receipt,id:++G.nextLoanId,status:'default',balance:17,defaultedDay:G.day},{...receipt,id:++G.nextLoanId,status:'active',balance:23,ownerType:'firm',ownerId:0}];const incomplete={...receipt,id:++G.nextLoanId};delete incomplete.paid;protectedRows.push(incomplete);G.loans.push(...protectedRows);const protectedJSON=JSON.stringify(protectedRows);if(!hydrateSave(archivePayload()))throw Error('Historical boundary rejected');const money=totalMoney(),before=archivePayload(),next=G.nextLoanId;const issued=bankLoan('household',h.id,100,360);if(!issued)throw Error('Boundary credit refused');const after=archivePayload(),accepted=hydrateSave(after);if(!accepted)hydrateSave(before);if(accepted&&JSON.stringify(G.loans.filter(l=>protectedRows.some(p=>p.id===l.id)))!==protectedJSON)throw Error('Protected claim lost');if(accepted){const raw=archivePayload(),bad=JSON.parse(raw);bad.settledLoanHistory.paid=-1;if(hydrateSave(bad)||archivePayload()!==raw)throw Error('Bad summary not atomic');const canon=g=>Array.isArray(g)?g.map(canon):g&&typeof g==='object'?Object.fromEntries(Object.keys(g).sort().map(k=>[k,canon(g[k])])):g;__townTest.step(30);const a=JSON.parse(archivePayload());if(!hydrateSave(raw))throw Error('Replay restore');__townTest.step(30);const b=JSON.parse(archivePayload());for(const g of[a,b]){delete g.trafficState;delete g.visualState;}if(JSON.stringify(canon(a))!==JSON.stringify(canon(b)))throw Error('Replay changed');}if(Math.abs(totalMoney()-money)>.001)throw Error('Loan/pruning changed money');return {actualRepayment:true,syntheticHistoricalReceipts:10000,newLoanId:issued.id,priorMaximum:next,newArchiveImportable:accepted,retained:G.loans.length,protectedClaimsPreserved:accepted,exactReplayDays:accepted?30:0,summary:G.settledLoanHistory||null,moneyPreserved:true};};
'''
