negative=os.environ.get('LOAN_EXPECT_NEGATIVE')=='1';assert r['newArchiveImportable']!=negative,r;out=ROOT/'reports/loan-history';out.mkdir(exist_ok=True);(out/('before.json' if negative else 'after.json')).write_text(json.dumps({'source_sha256':hashlib.sha256(source.encode()).hexdigest(),'result':r},indent=2)+'\n');print('PASS',r)
